                if ((diff.operation == .insert)) {
                    if (((diff_segments.items.len > 0) and (diff_segments.items[@as(usize, @intCast((diff_segments.items.len - 1)))].mode == .removed))) {
                        diff_segments.items[@as(usize, @intCast((diff_segments.items.len - 1)))].inserted = diff.text;
                        diff_segments.items[@as(usize, @intCast((diff_segments.items.len - 1)))].mode = .modified;
                    } else {
                        _ = bun.handleOom(diff_segments.append(DiffSegment{ .removed = "", .inserted = diff.text, .mode = .inserted }));
                    }
                } else {
                    if ((diff.operation == .equal)) {
                        _ = bun.handleOom(diff_segments.append(DiffSegment{ .removed = diff.text, .inserted = diff.text, .mode = .equal }));
                    }
                }
            }
        }
        if ((diff_segments.items.len > 0)) {
            for (cp_mut_slice(&diff_segments.items[0..(diff_segments.items.len - 1)])) |*diff_segment| {
                _ = &diff_segment;
                (diff_segment.*).removed = removeTrailingNewline((diff_segment.*).removed);
                (diff_segment.*).inserted = removeTrailingNewline((diff_segment.*).inserted);
            }
        }
        if (((expected_slice.len > config.min_bytes_before_chunking) or (received_slice.len > config.min_bytes_before_chunking))) {
            var new_diff_segments = std.array_list.Managed(DiffSegment).init(allocator);
            _ = &new_diff_segments;
            for (diff_segments.items) |diff_segment| {
                _ = &diff_segment;
                if ((diff_segment.mode == .equal)) {
                    var split = std.mem.splitScalar(u8, diff_segment.removed, 10);
                    _ = &split;
                    while (split.next()) |line| {
                        _ = bun.handleOom(new_diff_segments.append(DiffSegment{ .removed = line, .inserted = line, .mode = .equal, .skip = true }));
                    }
                } else {
                    _ = bun.handleOom(new_diff_segments.append(diff_segment));
                }
            }
            diff_segments = new_diff_segments;
            var fwd_i: usize = 0;
            _ = &fwd_i;
            for (diff_segments.items) |segment| {
                _ = &segment;
                defer {
                fwd_i = (fwd_i + 1);
                }
                if ((segment.mode != .equal)) {
                    const end = @min(((fwd_i +| config.chunk_context_lines) +| 1), diff_segments.items.len);
                    for (cp_mut_slice(&diff_segments.items[fwd_i..end])) |*seg| {
                        _ = &seg;
                        (seg.*).skip = false;
                    }
                }
            }
            {
                var i = diff_segments.items.len;
                _ = &i;
                while ((i > 0)) {
                    i = (i - 1);
                    const segment = diff_segments.items[@as(usize, @intCast(i))];
                    if ((segment.mode != .equal)) {
                        const start = (i -| config.chunk_context_lines);
                        for (cp_mut_slice(&diff_segments.items[start..(i + 1)])) |*seg| {
                            _ = &seg;
                            (seg.*).skip = false;
                        }
                    }
                }
            }
        }
        for (diff_segments.items) |*item| {
            _ = &item;
            for (cp_iter_slice((item.*).removed)) |char| {
                _ = &char;
                if ((char == 10)) {
                    (item.*).removed_line_count = ((item.*).removed_line_count + 1);
                }
            }
            (item.*).removed_line_count = ((item.*).removed_line_count + 1);
            for (cp_iter_slice((item.*).inserted)) |char| {
                _ = &char;
                if ((char == 10)) {
                    (item.*).inserted_line_count = ((item.*).inserted_line_count + 1);
                }
            }
            (item.*).inserted_line_count = ((item.*).inserted_line_count + 1);
        }
        _ = try printDiff(allocator, writer, diff_segments.items, config);
}

pub fn printDiffFooter(writer: anytype, config: DiffConfig, removed_diff_lines: usize, inserted_diff_lines: usize) !void {
        if (config.enable_ansi_colors) {
            _ = try writer.writeAll(styles.removed_line.prefix.color);
        }
        _ = try writer.writeAll(styles.removed_line.prefix.msg);
        _ = try writer.writeAll("Expected");
        _ = try writer.print("  {s}{d}", .{ styles.removed_line.prefix.msg, removed_diff_lines });
        if (config.enable_ansi_colors) {
            _ = try writer.writeAll(colors.reset);
        }
        _ = try writer.writeAll("\n");
        if (config.enable_ansi_colors) {
            _ = try writer.writeAll(styles.inserted_line.prefix.color);
        }
        _ = try writer.writeAll(styles.inserted_line.prefix.msg);
        _ = try writer.writeAll("Received");
        _ = try writer.print("  {s}{d}", .{ styles.inserted_line.prefix.msg, inserted_diff_lines });
        if (config.enable_ansi_colors) {
            _ = try writer.writeAll(colors.reset);
        }
}

pub fn printLinePrefix(writer: anytype, config: DiffConfig, prefix: PrefixStyle) !void {
        if (config.enable_ansi_colors) {
            _ = try writer.writeAll(prefix.color);
        }
        _ = try writer.writeAll(prefix.msg);
        if (config.enable_ansi_colors) {
            _ = try writer.writeAll(colors.reset);
        }
}

pub fn printTruncatedLine(line: []const u8, writer: anytype, config: DiffConfig, style: Style) !void {
        if (((line.len <= config.truncate_threshold) or (line.len <= (config.truncate_context * 2)))) {
            if (config.enable_ansi_colors) {
                _ = try writer.writeAll(style.text_color);
            }
            _ = try writer.writeAll(line);
            if (config.enable_ansi_colors) {
                _ = try writer.writeAll(colors.reset);
            }
            return;
        }
        if (config.enable_ansi_colors) {
            _ = try writer.writeAll(style.text_color);
        }
        _ = try writer.writeAll(line[0..config.truncate_context]);
        if (config.enable_ansi_colors) {
            _ = try writer.writeAll(colors.reset);
        }
        if (config.enable_ansi_colors) {
            _ = try writer.writeAll(colors.white);
        }
        _ = try writer.print("... ({} bytes truncated) ...", .{ (line.len - (2 * config.truncate_context)) });
        if (config.enable_ansi_colors) {
            _ = try writer.writeAll(colors.reset);
        }
        if (config.enable_ansi_colors) {
            _ = try writer.writeAll(style.text_color);
        }
        _ = try writer.writeAll(line[(line.len - config.truncate_context)..]);
        if (config.enable_ansi_colors) {
            _ = try writer.writeAll(colors.reset);
        }
}

pub fn printSegment(text: []const u8, writer: anytype, config: DiffConfig, style: Style) !void {
        var lines = std.mem.splitScalar(u8, text, 10);
        _ = &lines;
        _ = try printTruncatedLine((lines.next()).?, writer, config, style);
        while (lines.next()) |line| {
            _ = try writer.writeAll("\n");
            _ = try printLinePrefix(writer, config, style.prefix);
            _ = try printTruncatedLine(line, writer, config, style);
        }
}

pub fn printModifiedSegmentWithoutDiffdiff(writer: anytype, config: DiffConfig, segment: DiffSegment, modified_style: ModifiedStyle) !void {
        const removed_prefix = (if (modified_style.single_line) prefix_styles.single_line_removed else prefix_styles.removed);
        const inserted_prefix = (if (modified_style.single_line) prefix_styles.single_line_inserted else prefix_styles.inserted);
        _ = try printLinePrefix(writer, config, removed_prefix);
        _ = try printSegment(segment.removed, writer, config, styles.removed_line);
        _ = try writer.writeAll("\n");
        _ = try printLinePrefix(writer, config, inserted_prefix);
        _ = try printSegment(segment.inserted, writer, config, styles.inserted_line);
        if ((!modified_style.single_line)) {
            _ = try writer.writeAll("\n");
        }
}

pub fn shouldHighlightChar(char: u8) bool {
        if ((char <= 32)) {
            return true;
        }
        if ((char == 127)) {
            return true;
        }
        return false;
}

pub fn printModifiedSegment(segment: DiffSegment, allocator: std.mem.Allocator, writer: anytype, config: DiffConfig, modified_style: ModifiedStyle) std.Io.Writer.Error!void {
        const removed_prefix = (if (modified_style.single_line) prefix_styles.single_line_removed else prefix_styles.removed);
        const inserted_prefix = (if (modified_style.single_line) prefix_styles.single_line_inserted else prefix_styles.inserted);
        if ((mode == .fg)) {
            return printModifiedSegmentWithoutDiffdiff(writer, config, segment, modified_style);
        }
        var char_diff = bun.handleOom(DMP.default.diff(allocator, segment.removed, segment.inserted, true));
        _ = &char_diff;
        _ = bun.handleOom(DMP.diffCleanupSemantic(allocator, (&char_diff)));
        var deleted_highlighted_length: usize = 0;
        _ = &deleted_highlighted_length;
        var inserted_highlighted_length: usize = 0;
        _ = &inserted_highlighted_length;
        var unhighlighted_length: usize = 0;
        _ = &unhighlighted_length;
        for (char_diff.items) |item| {
            _ = &item;
            switch (item.operation) {
.delete => {
deleted_highlighted_length = (deleted_highlighted_length + item.text.len);
},
.insert => {
inserted_highlighted_length = (inserted_highlighted_length + item.text.len);
},
.equal => {
unhighlighted_length = (unhighlighted_length + item.text.len);
},
}
        }
        if ((((deleted_highlighted_length > 10) and (deleted_highlighted_length > ((segment.removed.len / 3) * 2))) or ((inserted_highlighted_length > 10) and (inserted_highlighted_length > ((segment.inserted.len / 3) * 2))))) {
            return printModifiedSegmentWithoutDiffdiff(writer, config, segment, modified_style);
        }
        var is_valid_utf_8 = true;
        _ = &is_valid_utf_8;
        for (char_diff.items) |item| {
            _ = &item;
            if ((!bun.strings.isValidUTF8(item.text))) {
                is_valid_utf_8 = false;
                break;
            }
        }
        if ((!is_valid_utf_8)) {
            return printModifiedSegmentWithoutDiffdiff(writer, config, segment, modified_style);
        }
        _ = try printLinePrefix(writer, config, removed_prefix);
        for (char_diff.items) |*item| {
            _ = &item;
            switch ((item.*).operation) {
.delete => {
var only_highlightable = true;
            _ = &only_highlightable;
            for (cp_iter_slice((item.*).text)) |char| {
                _ = &char;
                if ((!shouldHighlightChar(char))) {
                    only_highlightable = false;
                    break;
                }
            }
            if (only_highlightable) {
                _ = try printSegment((item.*).text, writer, config, base_styles.green_bg_removed);
            } else {
                _ = try printSegment((item.*).text, writer, config, styles.removed_diff);
            }
},
.insert => {

},
.equal => {
_ = try printSegment((item.*).text, writer, config, styles.removed_equal);
},
}
        }
        _ = try writer.writeAll("\n");
        _ = try printLinePrefix(writer, config, inserted_prefix);
        for (char_diff.items) |*item| {
            _ = &item;
            switch ((item.*).operation) {
.delete => {

},
.insert => {
var only_highlightable = true;
            _ = &only_highlightable;
            for (cp_iter_slice((item.*).text)) |char| {
                _ = &char;
                if ((!shouldHighlightChar(char))) {
                    only_highlightable = false;
                    break;
                }
            }
            if (only_highlightable) {
                _ = try printSegment((item.*).text, writer, config, base_styles.red_bg_inserted);
            } else {
                _ = try printSegment((item.*).text, writer, config, styles.inserted_diff);
            }
},
.equal => {
_ = try printSegment((item.*).text, writer, config, styles.inserted_equal);
},
}
        }
        if ((!modified_style.single_line)) {
            _ = try writer.writeAll("\n");
        }
}

pub fn printHunkHeader(writer: anytype, config: DiffConfig, original_line_number: usize, original_line_count: usize, changed_line_number: usize, changed_line_count: usize) !void {
        if (config.enable_ansi_colors) {
            _ = try writer.print("{s}@@ -{},{} +{},{} @@{s}\n", .{ colors.yellow, original_line_number, original_line_count, changed_line_number, changed_line_count, colors.reset });
        } else {
            _ = try writer.print("@@ -{},{} +{},{} @@\n", .{ original_line_number, original_line_count, changed_line_number, changed_line_count });
        }
}

pub fn printDiff(allocator: std.mem.Allocator, writer: anytype, diff_segments: []const DiffSegment, config: DiffConfig) std.Io.Writer.Error!void {
        var removed_line_number: usize = 1;
        _ = &removed_line_number;
        var inserted_line_number: usize = 1;
        _ = &inserted_line_number;
        var removed_diff_lines: usize = 0;
        _ = &removed_diff_lines;
        var inserted_diff_lines: usize = 0;
        _ = &inserted_diff_lines;
        var has_skipped_segments = false;
        _ = &has_skipped_segments;
        for (cp_iter_slice(diff_segments)) |seg| {
            _ = &seg;
            if (seg.skip) {
                has_skipped_segments = true;
                break;
            }
        }
        var was_skipped = false;
        _ = &was_skipped;
        var seg_i: usize = 0;
        _ = &seg_i;
        for (cp_iter_slice(diff_segments)) |segment| {
            _ = &segment;
            defer {
            {
                removed_line_number = (removed_line_number + segment.removed_line_count);
                inserted_line_number = (inserted_line_number + segment.inserted_line_count);
                seg_i = (seg_i + 1);
            }
            }
            if (((was_skipped and (!segment.skip)) or ((has_skipped_segments and (seg_i == 0)) and (!segment.skip)))) {
                var original_line_count: usize = 0;
                _ = &original_line_count;
                var changed_line_count: usize = 0;
                _ = &changed_line_count;
                for (cp_iter_slice(diff_segments[seg_i..])) |seg| {
                    _ = &seg;
                    if (seg.skip) {
                        break;
                    }
                    original_line_count = (original_line_count + seg.removed_line_count);
                    changed_line_count = (changed_line_count + seg.inserted_line_count);
                }
                _ = try printHunkHeader(writer, config, removed_line_number, original_line_count, inserted_line_number, changed_line_count);
                was_skipped = false;
            }
            switch (segment.mode) {
.equal => {
if (segment.skip) {
                was_skipped = true;
                continue;
            }
            _ = try printLinePrefix(writer, config, prefix_styles.equal);
            _ = try printSegment(segment.removed, writer, config, styles.equal);
            _ = try writer.writeAll("\n");
},
.removed => {
_ = try printLinePrefix(writer, config, prefix_styles.removed);
            _ = try printSegment(segment.removed, writer, config, styles.removed_line);
            _ = try writer.writeAll("\n");
            removed_diff_lines = (removed_diff_lines + segment.removed_line_count);
},
.inserted => {
_ = try printLinePrefix(writer, config, prefix_styles.inserted);
            _ = try printSegment(segment.inserted, writer, config, styles.inserted_line);
            _ = try writer.writeAll("\n");
            inserted_diff_lines = (inserted_diff_lines + segment.inserted_line_count);
},
.modified => {
_ = try printModifiedSegment(segment, allocator, writer, config, ModifiedStyle{ .single_line = false });
            removed_diff_lines = (removed_diff_lines + segment.removed_line_count);
            inserted_diff_lines = (inserted_diff_lines + segment.inserted_line_count);
},
}
        }
        _ = try writer.writeAll("\n");
        _ = try printDiffFooter(writer, config, removed_diff_lines, inserted_diff_lines);
}
